const DB_STORE='files';
const SYMBOLS=['🍽️','🥂','☕','🥐','🍕','🍝','🍔','🥗','🍣','🍜','🌮','🍰','🍷','🌇','🏙️','🗼','❤️','✨'];
const QUICK_FILTERS=[['🍽️','Entdecken','Restaurants'],['🍝','Pasta','Pasta Restaurant'],['🌱','Vegetarisch','vegetarische Restaurants'],['☕','Café','Café'],['🥐','Frühstück','Frühstück Café'],['🍕','Pizza','Pizzeria'],['🍔','Burger','Burger Restaurant'],['🍣','Sushi','Sushi Restaurant'],['🍷','Romantisch','romantisches Restaurant'],['🌇','Rooftop','Rooftop Restaurant Aussicht']];
const clone=v=>JSON.parse(JSON.stringify(v));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>`restaurant-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
let defaults=null;
function parse(v,f=null){try{const x=JSON.parse(v);return x==null?f:x}catch{return f}}
function deepMerge(base,over){if(Array.isArray(over))return clone(over);if(!over||typeof over!=='object')return over??clone(base);const out=clone(base||{});Object.keys(over).forEach(k=>out[k]=over[k]&&typeof over[k]==='object'&&!Array.isArray(over[k])?deepMerge(out[k],over[k]):clone(over[k]));return out}
async function loadDefaults(){if(defaults)return clone(defaults);try{const r=await fetch(DATA_URL,{cache:'no-store'});if(!r.ok)throw new Error(r.status);defaults=await r.json()}catch(e){defaults={version:2.2,settings:{showEditor:true,showCountdown:true,showDiscovery:true},heading:{eyebrowTemplate:'Genussmomente in {destination}',title:'Unsere Restaurants',descriptionTemplate:'Reservierungen, Lieblingsorte und kulinarische Ideen für {destination}.'},entries:[],officialParisEntries:[]};console.warn('Restaurants V2 JSON konnte nicht geladen werden.',e)}return clone(defaults)}
function activeTripFallback(){return window.LuviaTripContext?.getActiveTrip?.()||window.LuviaAppState?.getSnapshot?.()?.trip?.trip||parse(localStorage.getItem('parisIdentityV1'),null)||null}
function compactObject(value){if(!value||typeof value!=='object')return{};return Object.fromEntries(Object.entries(value).filter(([,v])=>v!==undefined&&v!==null&&v!==''))}
function resolveTrip(input){const candidate=input?.trip||input||{};const contextTrip=window.LuviaTripContext?.getActiveTrip?.()||window.LuviaAppState?.getSnapshot?.()?.trip?.trip||{};const activeId=contextTrip.tripId||candidate.tripId||parse(localStorage.getItem('parisIdentityV1'),{})?.tripId;const registry=parse(localStorage.getItem('parisTripRegistryV1'),[])||[];const fromRegistry=activeId?registry.find(t=>t?.tripId===activeId)||{}:{};const sameCandidate=!candidate.tripId||!activeId||candidate.tripId===activeId;return {...compactObject(sameCandidate?candidate:{}),...compactObject(fromRegistry),...compactObject(contextTrip),tripId:activeId||candidate.tripId||fromRegistry.tripId||''}}
function cleanDestination(value){const raw=value&&typeof value==='object'?(value.canonicalCity?.name||value.name||value.displayName||value.city):value;const v=String(raw||'').trim();if(!v||/^(unser(?:em|e|es)?|euer(?:em|e|es)?)?\s*reiseziel$/i.test(v)||/^destination$/i.test(v))return'';return v}
function tripContext(input){const trip=resolveTrip(input);const refreshed=window.LuviaDestination?.getActive?.({refresh:true})||null;const normalized=window.LuviaDestination?.normalize?.(trip)||window.LuviaDestinationContext?.normalize?.(trip)||null;const resolved=window.LuviaDestination?.resolve?.(trip,{refresh:true})||window.LuviaIntelligence?.destination?.(trip)||null;const embedded=trip?.destination_context||trip?.destinationContext||null;const appDestination=window.LuviaAppState?.getSnapshot?.()?.trip?.destination||window.LuviaTripContext?.getDestination?.();const candidates=[refreshed,resolved,normalized,embedded].filter(Boolean);const matching=candidates.find(item=>!item.tripId||!trip.tripId||item.tripId===trip.tripId&&cleanDestination(item?.canonicalCity?.name||item?.name));const destinationContext=matching||candidates.find(item=>cleanDestination(item?.canonicalCity?.name||item?.name))||null;const destination=cleanDestination(destinationContext?.canonicalCity?.name||destinationContext?.name||trip.destinationName||trip.destination||trip.city||appDestination)||'eurem Reiseziel';const accent=String(trip.accent||window.LuviaAppState?.getSnapshot?.()?.trip?.accent||getComputedStyle(document.documentElement).getPropertyValue('--trip-accent')||'#a23d63').trim();return {trip,destination,destinationContext,hasDestination:destination!=='eurem Reiseziel',tripName:String(trip.tripName||'Unsere Reise').trim(),startDate:trip.startDate||'',endDate:trip.endDate||'',accent:/^#[0-9a-f]{6}$/i.test(accent)?accent:'#a23d63'}}
function template(text,ctx){return String(text||'').replace(/\{(destination|tripName|startDate|endDate)\}/g,(_,k)=>ctx[k]||'')}
function weekday(date){if(!date)return'';const d=new Date(date+'T12:00:00');return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('de-DE',{weekday:'long'}).format(d)}
function displayDate(date){if(!date)return'Datum offen';const d=new Date(date+'T12:00:00');return Number.isNaN(d.getTime())?date:new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d)}
function generatedMapsUrl(entry,ctx){const parts=[entry.name,entry.address];if(ctx.hasDestination&&!String(entry.address||'').toLowerCase().includes(ctx.destination.toLowerCase()))parts.push(ctx.destination);const q=parts.filter(Boolean).join(' ');return q?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q):''}
function validCustomMaps(url){const v=String(url||'').trim();if(!v)return'';if(/unserem(%20|\s)+reiseziel|\breiseziel\b/i.test(decodeURIComponentSafe(v)))return'';return v}
function decodeURIComponentSafe(v){try{return decodeURIComponent(v)}catch{return v}}
function countdown(entry){if(!entry.date)return'';const t=new Date(`${entry.date}T${entry.time||'12:00'}:00`),diff=t-Date.now();if(Number.isNaN(t.getTime()))return'';if(diff< -21600000)return'Dieser Restaurantmoment liegt hinter euch.';if(diff<=0)return'Dieser Moment ist jetzt da ✨';const days=Math.floor(diff/86400000),hours=Math.floor(diff/3600000)%24,mins=Math.floor(diff/60000)%60;return days>0?`Noch ${days} ${days===1?'Tag':'Tage'} · ${hours} Std.`:`Noch ${hours} Std. · ${mins} Min.`}
function statusLabel(s){return({confirmed:'Reserviert',idea:'Idee',requested:'Angefragt',cancelled:'Abgesagt'})[s]||'Geplant'}
function demoKey(trip){return DEMO_KEY+(trip?.tripId||'default')}
function loadDemo(trip){return parse(localStorage.getItem(demoKey(trip)),null)}
function saveDemo(trip,data){localStorage.setItem(demoKey(trip),JSON.stringify(data))}
function normalize(data,ctx){const m=clone(data||{});m.version=2.2;m.heading=m.heading||{};m.settings={showEditor:true,showCountdown:true,...(m.settings||{}),showDiscovery:true};m.archived=Array.isArray(m.archived)?m.archived:[];m.entries=(m.entries||[]).map((e,i)=>{const custom=validCustomMaps(e.mapsUrl);return {...e,id:e.id||uid(),name:e.name||`Restaurant ${i+1}`,symbol:SYMBOLS.includes(e.symbol)?e.symbol:(e.symbol||'🍽️'),mapsUrl:custom,menu:{enabled:false,label:'Speisekarte',original:'',assetId:'',assetName:'',pages:[],...(e.menu||{})}}});return m}
async function modelFor(input){const ctx=tripContext(input),trip=ctx.trip,base=await loadDefaults(),official=window.LuviaModules?.isOfficialParis?.(trip);let seed={...base,entries:official?clone(base.officialParisEntries||[]):[]};delete seed.officialParisEntries;const stored=window.LuviaModules?.getModuleData?.(MODULE_ID,trip);const demo=official?loadDemo(trip):null;const hasStored=stored&&typeof stored==='object'&&Object.keys(stored).length>0;const model=normalize(deepMerge(seed,demo||(hasStored?stored:{})),ctx);if(!official&&window.LuviaRestaurants&&trip?.tripId){try{const [response,historyResponse]=await Promise.all([window.LuviaRestaurants.list({tripId:trip.tripId}),window.LuviaRestaurants.history?.({tripId:trip.tripId}).catch(()=>({data:{entities:[]}}))]);const entities=response?.data?.entities||[];const archivedEntities=historyResponse?.data?.entities||[];const entityEntries=entities.map(window.LuviaRestaurants.entityToEntry);model.archived=archivedEntities.map(window.LuviaRestaurants.entityToEntry);const legacy=model.entries.filter(e=>!e.entity);model.entries=[...entityEntries,...legacy.filter(e=>!entityEntries.some(x=>x.providerPlaceId&&x.providerPlaceId===e.providerPlaceId))];}catch(error){console.warn('Restaurant Entities konnten nicht geladen werden.',error)}}if(window.LuviaRestaurantIntelligence)model.entries=await window.LuviaRestaurantIntelligence.enhance(model.entries,{intent:'saved'});return model}
const LIFECYCLE_ORDER=['discovered','saved','favorited','planned','reserved','visited','rated','memory','travel_book'];
function lifecycleLabel(value){return({discovered:'Entdeckt',saved:'Gespeichert',favorited:'Favorisiert',planned:'Geplant',reserved:'Reserviert',visited:'Besucht',rated:'Bewertet',memory:'Erinnerung',travel_book:'Reisebuch'})[value]||'Entdeckt'}
function locationPanel(){const c=window.LuviaTravelContext?.snapshot?.()||{};if(c.location)return `<div class="rv2-context-bar is-active"><div><strong>📍 Entfernung ab deinem Standort</strong><span>${esc(c.weekday||'Heute')} · Restauranttreffer werden nach Nähe ergänzt.</span></div><button type="button" data-rv2-location-refresh>Aktualisieren</button></div>`;return `<div class="rv2-context-bar"><div><strong>📍 Restaurants in deiner Nähe</strong><span>Standort freiwillig freigeben, damit Luvia echte Entfernung und passendere Vorschläge zeigt.</span></div><button type="button" data-rv2-location-enable>${c.requesting?'Standort wird ermittelt …':'Standort erlauben'}</button></div>`}
function entryDistance(entry){const d=window.LuviaTravelContext?.distanceTo?.({latitude:entry.latitude,longitude:entry.longitude});return formatDistance(Number.isFinite(d)?d:entry.distanceMeters)}
function lifecycleTimeline(status){const index=Math.max(0,LIFECYCLE_ORDER.indexOf(status||'discovered'));return `<div class="rv2-lifecycle"><span>Restaurant-Lebenszyklus</span><div>${LIFECYCLE_ORDER.map((x,i)=>`<em class="${i<=index?'done':''}" title="${lifecycleLabel(x)}">${i<index?'✓':i===index?'●':'○'}</em>`).join('')}</div><strong>${lifecycleLabel(LIFECYCLE_ORDER[index])}</strong></div>`}
function discoveryQueries(){return QUICK_FILTERS}
function searchUrl(q){return'https://www.google.com/search?q='+encodeURIComponent(q)}
function priceLabel(level){const map={PRICE_LEVEL_FREE:'Kostenlos',PRICE_LEVEL_INEXPENSIVE:'€',PRICE_LEVEL_MODERATE:'€€',PRICE_LEVEL_EXPENSIVE:'€€€',PRICE_LEVEL_VERY_EXPENSIVE:'€€€€'};return map[level]||(/^[1-4]$/.test(String(level))?'€'.repeat(Number(level)):'Preis offen')}
function formatDistance(value){const n=Number(value);if(!Number.isFinite(n))return'';return n<1000?`${Math.round(n)} m`:`${(n/1000).toFixed(1).replace('.',',')} km`}
function experienceTags(place){const text=[place.name,place.editorialSummary,...(place.types||[])].join(' ').toLowerCase(),f=place.features||{},tags=[];if(f.servesVegetarianFood===true||/vegetar|vegan/.test(text))tags.push(['🌱','Vegetarische Auswahl']);if(/rooftop|terrasse|roof|aussicht|panoram/.test(text))tags.push(['🌇','Besondere Aussicht']);if(/romanti|date|intim|elegant|fine.dining/.test(text))tags.push(['❤️','Romantisch']);if(/café|coffee|bakery|breakfast/.test(text)||f.breakfast===true)tags.push(['☕','Frühstück & Café']);if(f.reservable===true)tags.push(['📅','Reservierbar']);if(f.dineIn===true)tags.push(['🍽️','Vor Ort essen']);if(f.wine===true||f.beer===true)tags.push(['🍷','Drinks']);if(place.rating>=4.5&&place.userRatingCount>=200)tags.push(['✨','Sehr beliebt']);if(place.accessibility&&Object.values(place.accessibility).some(Boolean))tags.push(['♿','Barrierearme Angaben']);if(!tags.length)tags.push(['📍','Passend zum Reiseziel']);return tags.slice(0,6)}
function matchReasons(place){const reasons=[...(window.LuviaTravelPreferences?.reasons?.(place,'restaurants',4)||[])];const distance=Number(place?.distanceMeters);if(place?.features?.servesVegetarianFood===true)reasons.push('Vegetarische Auswahl passt zu euren Präferenzen.');if(place?.features?.reservable===true)reasons.push('Reservierbar und dadurch gut planbar.');if(Number.isFinite(distance))reasons.push(distance<1500?'Sehr nah an deinem aktuellen Standort.':distance<5000?'Gut von deinem aktuellen Standort erreichbar.':'Als besonderes Ziel für den Tagesplan geeignet.');if(Number(place?.rating)>=4.5)reasons.push('Überdurchschnittlich gut bewertet.');if(place?.openNow===true)reasons.push('Aktuell geöffnet.');if(!reasons.length)reasons.push('Passt zum Ziel und zum Kontext eurer Reise.');return reasons.slice(0,4)}
function calculateMatchScore(place){let score=58+(window.LuviaTravelPreferences?.score?.(place,'restaurants')||0);const rating=Number(place?.rating)||0,reviews=Number(place?.userRatingCount)||0,distance=Number(place?.distanceMeters);score+=Math.max(0,(rating-3.5)*14);score+=Math.min(10,Math.log10(Math.max(1,reviews))*3);if(place?.features?.servesVegetarianFood===true)score+=7;if(place?.features?.reservable===true)score+=4;if(Number.isFinite(distance))score+=distance<1500?8:distance<5000?5:distance<12000?2:-3;return Math.max(55,Math.min(98,Math.round(score)))}
function normalizeMatchScore(place){if(!place||typeof place!=='object')return place;const provided=Number(place.matchScore),calculated=calculateMatchScore(place);const resolved=Number.isFinite(provided)&&provided>55?Math.round(provided):calculated;return {...place,matchScore:Math.max(55,Math.min(98,resolved))}}
function matchScore(place){return normalizeMatchScore(place)?.matchScore??55}
function quickFilters(){return `<div class="rv2-quick-wrap"><span class="rv2-quick-label">Direkt entdecken</span><div class="rv2-discovery-actions" role="list" aria-label="Restaurantkategorien">${QUICK_FILTERS.map(([icon,label,q],i)=>`<button type="button" role="listitem" class="rv2-quick-chip${i===0?' active':''}" data-rv2-query="${esc(q)}">${icon} ${esc(label)}</button>`).join('')}</div></div>`}
function favoriteEntries(model){return (model?.entries||[]).filter(e=>e.isFavorite===true||e.rawEntity?.tripPlace?.is_favorite===true)}
function favoritesPanel(model){const favorites=favoriteEntries(model);return `<details class="rv2-library-panel rv2-library-favorites"><summary><span><i>♥</i><span><strong>Lieblingsorte</strong><small>${favorites.length?`${favorites.length} schnell erreichbar`:'Noch keine Favoriten'}</small></span></span><span class="rv2-library-summary-actions">${favorites.length?`<button type="button" class="rv2-clear-all" data-rv2-clear="favorites">Alle entfernen</button>`:''}<b>${favorites.length}</b></span></summary><div class="rv2-library-content">${favorites.length?`<div class="rv2-favorite-list">${favorites.map(e=>`<article class="rv2-favorite-card" data-rv2-open-workspace="${esc(e.id)}"><div class="rv2-favorite-icon">${esc(e.symbol||'🍽️')}</div><div class="rv2-favorite-copy"><strong>${esc(e.name)}</strong><small>${esc(e.address||'In eurer Reise gespeichert')}</small></div><div class="rv2-favorite-actions"><button type="button" data-rv2-workspace="${esc(e.id)}">Öffnen</button><button type="button" class="danger" data-rv2-unfavorite="${esc(e.id)}" aria-label="${esc(e.name)} aus Favoriten entfernen">Entfernen</button></div></article>`).join('')}</div>`:'<div class="rv2-library-empty">Markiert Orte mit einem Herz, um sie hier schnell wiederzufinden.</div>'}</div></details>`}
