function discovery(ctx){if(!ctx.hasDestination)return `<section class="rv2-discovery"><div class="rv2-discovery-copy"><span class="rv2-discovery-kicker">Reiseziel wird vorbereitet</span><h3>Restaurants entdecken</h3><p>Der Zielkontext ist noch nicht vollständig geladen. Luvia versucht ihn automatisch wiederherzustellen.</p><div class="rv2-search-status">Bitte kurz warten oder zum Dashboard zurückkehren und das Modul erneut öffnen.</div></div></section>`;return `<section class="rv2-discovery rv2-discovery-new"><div class="rv2-discovery-copy"><div class="rv2-discovery-title"><div><span class="rv2-discovery-kicker">Für euch in ${esc(ctx.destination)}</span><h3>Worauf habt ihr Lust?</h3><p>Direkte Vorschläge aus eurem Reisekontext – ohne erst suchen zu müssen.</p></div><span class="rv2-smart-pill">Live empfohlen</span></div><form class="rv2-entity-search rv2-entity-search-new" data-rv2-search-form><label class="rv2-search-box"><span aria-hidden="true">⌕</span><input name="query" minlength="2" placeholder="Restaurant, Küche oder Stimmung" aria-label="Restaurants suchen" autocomplete="off"><button type="submit" class="rv2-search-submit">Suchen</button></label><div class="rv2-quick-row">${quickFilters()}</div><details class="rv2-filter-drawer"><summary>Suche verfeinern</summary><div class="rv2-search-options"><select name="minRating" aria-label="Mindestbewertung"><option value="">Alle Bewertungen</option><option value="4">ab 4,0 ★</option><option value="4.5">ab 4,5 ★</option></select><select name="sortBy" aria-label="Sortierung"><option value="relevance">Beste Treffer</option><option value="distance">Entfernung</option><option value="rating">Bewertung</option><option value="reviews">Anzahl Bewertungen</option></select><label class="rv2-check"><input type="checkbox" name="openNow"> Jetzt geöffnet</label><label class="rv2-check"><input type="checkbox" name="vegetarianOnly"> Vegetarisch priorisieren</label>${locationPanel()}</div></details></form><div class="rv2-recommendation-head"><div><span>Persönliche Auswahl</span><h4>Gerade passend für euch</h4></div><button type="button" data-rv2-refresh-suggestions>Aktualisieren</button></div><div class="rv2-search-status" data-rv2-search-status aria-live="polite">Vorschläge werden vorbereitet …</div><div class="rv2-search-results" data-rv2-search-results></div></div></section>`}
function restaurantIntel(place){const base=place?.intelligence||window.LuviaRestaurantIntelligence?.enrich?.(place,[])?.intelligence||{score:matchScore(place),openLabel:place?.openNow===true?'Heute geöffnet':place?.openNow===false?'Heute geschlossen':'Öffnungszeiten prüfen',bestTime:place?.recommendedVisitTime||place?.time||'18:45',reservationHint:place?.features?.reservable===true?'Reservierung empfohlen':'Spontaner Besuch möglich',babyLabel:'Baby-Eignung prüfen',budgetLabel:'Passt zu eurem Budget',walkMinutes:null,driveMinutes:null,reasons:matchReasons(place),warnings:[],suggestions:[],alternatives:[]};const localDistance=formatDistance(place?.distanceMeters);return{...base,distanceLabel:localDistance||base.distanceLabel,reasons:matchReasons(place)}}
