async function removeFavorite(instance,entryId,button){const entry=instance.model?.entries?.find(x=>x.id===entryId);if(!entry?.tripPlaceId)return;const old=button?.textContent;if(button){button.disabled=true;button.textContent='Wird entfernt …'}try{const response=await window.LuviaRestaurants.updateLifecycle(entry.tripPlaceId,entry.lifecycleStatus||'saved',{isFavorite:false},{tripId:instance.trip?.tripId});await syncRestaurantLifecycleToPlaceCore(response?.data||entry.rawEntity||entry,instance,entry.lifecycleStatus||'saved',{isFavorite:false});const fresh=await modelFor(instance.trip);render(instance,instance.trip,fresh)}catch(error){if(button){button.disabled=false;button.textContent=old}alert(error.message||'Favorit konnte nicht entfernt werden.')}}
async function removeSavedRestaurant(instance,entryId,button){const entry=instance.model?.entries?.find(x=>x.id===entryId);if(!entry?.tripPlaceId)return;if(!confirm(`„${entry.name}“ wirklich aus dieser Reise entfernen?`))return;const old=button?.textContent;if(button){button.disabled=true;button.textContent='Wird entfernt …'}try{await window.LuviaRestaurants.remove(entry.tripPlaceId,{tripId:instance.trip?.tripId});try{window.LuviaPlaceCore?.removePlace?.(entry.placeId)}catch(_){}const fresh=await modelFor(instance.trip);render(instance,instance.trip,fresh)}catch(error){if(button){button.disabled=false;button.textContent=old}alert(error.message||'Restaurant konnte nicht entfernt werden.')}}
async function clearRestaurantCollection(instance,scope,button){const label=scope==='favorites'?'alle Lieblingsmarkierungen entfernen':'alle gespeicherten Restaurants aus der Reise entfernen';if(!confirm(`Möchtet ihr wirklich ${label}?`))return;const old=button?.textContent;if(button){button.disabled=true;button.textContent='Wird entfernt …'}try{await window.LuviaRestaurants.clear(scope,{tripId:instance.trip?.tripId});const fresh=await modelFor(instance.trip);render(instance,instance.trip,fresh)}catch(error){if(button){button.disabled=false;button.textContent=old}alert(error.message||'Die Restaurants konnten nicht entfernt werden.')}}
async function importEntity(instance,placeId,button){button.disabled=true;const original=button.textContent;button.textContent='Wird hinzugefügt …';try{const response=await window.LuviaRestaurants.importPlace(placeId,{tripId:instance.trip?.tripId,regionCode:instance.ctx?.destinationContext?.countryCode||'DE'});button.textContent=response?.data?.alreadyAdded?'Bereits in der Reise':'Hinzugefügt ✓';const fresh=await modelFor(instance.trip);render(instance,instance.trip,fresh);window.dispatchEvent(new CustomEvent('luvia:restaurants-v2-updated',{detail:{tripId:instance.trip?.tripId,entityImport:true,data:response?.data}}));}catch(error){button.disabled=false;button.textContent=original;alert(error.message||'Restaurant konnte nicht hinzugefügt werden.')}}

function todayPlanPanel(){const schedule=window.LuviaScheduleIntelligence?.snapshot?.()||{};const items=(schedule.today||[]).filter(x=>x.entityType==='restaurant');if(!items.length)return '<section class="rv2-today-plan is-empty"><div><span>Heute geplant</span><h3>Noch kein Restaurant für heute</h3><p>Plant einen Ort mit Datum und Uhrzeit – er erscheint hier und im Dashboard.</p></div></section>';return `<section class="rv2-today-plan"><div class="rv2-today-plan-head"><div><span>Heute geplant</span><h3>Eure Restaurantmomente</h3></div><small>${items.length} ${items.length===1?'Ort':'Orte'}</small></div><div class="rv2-today-plan-list">${items.map(item=>`<article class="rv2-today-plan-item"><button type="button" class="rv2-today-plan-open" data-rv2-schedule-place="${esc(item.source?.providerPlaceId||item.id)}"><strong>${esc(item.time||new Date(item.startAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}))} Uhr</strong><span>${esc(item.title)}</span></button><button type="button" class="rv2-today-plan-remove" data-rv2-remove-schedule="${esc(item.id)}" aria-label="${esc(item.title)} löschen">Löschen</button></article>`).join('')}</div></section>`}
function render(instance,input,model){const ctx=tripContext(input),trip=ctx.trip;model=normalize(model&&typeof model==='object'?model:{heading:{},settings:{},entries:[]},ctx);const root=instance?.roots?.[0];if(!root)return;root.classList.add('luvia-restaurants-v2');root.style.setProperty('--module-accent',ctx.accent);root.style.setProperty('--trip-accent',ctx.accent);root.style.setProperty('--rv2-accent',ctx.accent);const saved=model.entries.filter(e=>!e.isFavorite);root.innerHTML=`<div class="rv2-shell"><header class="rv2-head rv2-head-new"><div class="rv2-head-copy"><span class="rv2-eyebrow">Luvia Places · ${esc(ctx.destination)}</span><h2>Genuss, der zu eurer Reise passt</h2><p>Entdecken, merken und planen – ruhig, persönlich und an einem Ort.</p></div></header>${todayPlanPanel()}${discovery(ctx)}<section class="rv2-library"><div class="rv2-library-heading"><div><span>Eure Sammlung</span><h3>Nur öffnen, wenn ihr sie braucht</h3></div><small>${model.entries.length} Orte</small></div>${favoritesPanel(model)}${savedPanel(saved,ctx,model.settings||{})}${deletedHistoryPanel(model.archived||[])}</section></div>`;root.dataset.luviaRendered='restaurants-v2-4';instance.model=model;instance.trip=trip;instance.ctx=ctx;queueMicrotask(()=>{if(!restoreSuggestions(instance)&&!instance.rv2AutoSuggested&&ctx.hasDestination){instance.rv2AutoSuggested=true;runEntitySearch(instance,'Restaurants',{sortBy:'relevance',openNow:false,vegetarianOnly:false,auto:true}).catch(()=>{})}})}
